/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'plot:view:browser:routes:events' );
var KEEP_ALIVE_INTERVAL = 10000; // milliseconds

// Define properties requiring a full spec refresh, grouped by event source. Properties in these lists cannot be dynamically updated via Vega signals and require re-parsing the entire specification...
var REFRESH_GENERAL_PROPS = [
	'width',
	'height',
	'description'
];
var REFRESH_AXIS_PROPS = [
	'aria',
	'description',
	'labelAlign',
	'labelBaseline',
	'labelBound',
	'labelFlush',
	'labelOverlap',
	'orient',
	'scale',
	'titleAngle',
	'titleBaseline',
	'titleX',
	'titleY',
	'zindex'
];

var isRefreshGeneralProp = contains( REFRESH_GENERAL_PROPS );
var isRefreshAxisProp = contains( REFRESH_AXIS_PROPS );


// FUNCTIONS //

/**
* Checks whether a change event requires a full specification refresh.
*
* @private
* @param {Object} event - change event object
* @returns {boolean} boolean indicating whether a refresh is needed
*/
function needsRefresh( event ) {
	var src = event.source;
	if ( src === 'padding' ) {
		return true;
	}
	if ( src === 'visualization' ) {
		return isRefreshGeneralProp( event.property );
	}
	if ( src === 'axis' ) {
		return isRefreshAxisProp( event.property );
	}
	return false;
}


// MAIN //

/**
* Callback invoked upon receiving an HTTP request.
*
* @private
* @param {Object} request - request object
* @param {Object} response - response object
* @returns {void}
*/
function handler( request, response ) {
	var counter;
	var timer;
	var self;
	var id;

	self = this;
	counter = 0;

	response.setHeader( 'Content-Type', 'text/event-stream' );
	response.setHeader( 'Cache-Control', 'no-cache' );

	id = request.headers[ 'Last-Event-ID' ];
	if ( id ) {
		debug( 'Client was previously connected. Checking for events to replay...' );
		debug( 'Last event id: %s', id );
		replay( id );
	}
	// Send an immediate ping in order to send some data over the wire:
	debug( 'Starting connection heartbeat...' );
	keepAlive();
	timer = setInterval( keepAlive, KEEP_ALIVE_INTERVAL );

	request.on( 'close', closeConnection );

	// Begin listening for plot "change" events:
	this.plot.on( 'change', onChange );

	/**
	* Callback invoked upon a plot "change" event.
	*
	* @private
	* @param {Event} event - event object
	* @returns {void}
	*/
	function onChange( event ) {
		var data;
		if ( event ) {
			if ( event.source === 'data' ) {
				// TODO: handle data change event

				// NOTE: for data changes, will also need to propagate plot changes (e.g., scales ranges might need updating, etc). Could first send property changes and, once sent, send over data changes.
				return;
			}
			// For properties that Vega cannot dynamically update via signals (e.g., structural axis props, width, height, padding), we need to push a fresh specification to the client...
			if ( needsRefresh( event ) ) {
				refresh();
				return;
			}
		}
		counter += 1;

		// FIXME: only send the JSON patch
		data = self.spec.toString();

		self.events.push({
			'id': counter.toString(),
			'type': 'patch',
			'data': data
		});

		debug( 'Sending a patch to the client...' );
		response.write( 'event: patch\n' );
		response.write( format( 'id: %d\n', counter ) );
		response.write( format( 'data: %s\n\n', data ) );
	}

	/**
	* Replays missed events.
	*
	* @private
	* @param {string} id - last event id
	* @returns {void}
	*/
	function replay( id ) {
		var payload;
		var evts;
		var N;
		var e;
		var i;

		evts = self.events;
		N = evts.length;
		for ( i = N-1; i >= 0; i-- ) {
			if ( evts[ i ].id === id ) {
				break;
			}
		}
		if ( i === N-1 ) {
			debug( 'No events to replay. Client has already received all events.' );
			return;
		}
		if ( i === -1 ) {
			debug( 'Client has missed all events.' );
			return refresh();
		}
		// Send the missed events to the client...
		debug( 'Client has missed %d events. Replaying...', N-i );
		payload = [];
		for ( ; i < N; i++ ) {
			e = evts[ i ];
			payload.push( format( 'event: %s', e.type ) );
			payload.push( format( 'id: %s', e.id ) );
			payload.push( format( 'data: %s\n\n', e.data ) );
		}
		response.write( join( payload, '\n' ) );
	}

	/**
	* Sends a "refresh" event to a connected client.
	*
	* @private
	*/
	function refresh() {
		var data;

		debug( 'Sending a new specification to client...' );

		counter += 1;
		data = JSON.stringify( self.plot );
		self.events.push({
			'id': counter.toString(),
			'type': 'refresh',
			'data': data
		});
		response.write( 'event: refresh\n' );
		response.write( format( 'id: %d\n', counter ) );
		response.write( format( 'data: %s\n\n', data ) );
	}

	/**
	* Sends a "keep-alive" message to a connected client.
	*
	* @private
	*/
	function keepAlive() {
		debug( 'Sending ping to client...' );
		response.write( 'event: ping\n' );
		response.write( 'data: ping\n\n' );
	}

	/**
	* Closes a long-lived connection.
	*
	* @private
	*/
	function closeConnection() {
		debug( 'Connection closed.' );
		self.plot.removeListener( 'change', onChange );
		clearInterval( timer );
		response.end();
	}
}


// EXPORTS //

module.exports = handler;
